 public LWS.TruckCornhole.CornholeMatch cornhole;public SportsChaosWeather weather;public SportsEventSession session;public LWS.TruckCheeseRolling.CheeseWeather cheese;public LWS.TruckBaseJumping.BaseJumpMatch baseJump;public TruckTaxiSnowSurface surface;public LwsWeatheradeAdapter adapter;public WheelController[] wheels;public Rigidbody[] broadBodies;public ParticleSystem[] spray;public Texture2D snowTexture,detailTexture,sparkleTexture;public Shader[] retainedShaders;public int depthRenderer=1;
 public bool traceExposedRoads;public int RoadContacts{get;private set;}readonly RaycastHit[] exposure=new RaycastHit[32];[Range(0,1)]public float permanentCoverage;public float Coverage{get;private set;}public int Contacts{get;private set;}public int BroadContacts{get;private set;}public bool Falling{get;private set;}
 readonly System.Collections.Generic.Dictionary<MeshRenderer,Material[]> originalRoads=new System.Collections.Generic.Dictionary<MeshRenderer,Material[]>();readonly System.Collections.Generic.Dictionary<Material,Material> runtimeRoads=new System.Collections.Generic.Dictionary<Material,Material>();public int RuntimeRoadMaterialCount=>runtimeRoads.Count;public bool RoadsInClearMode{get{foreach(var renderer in originalRoads.Keys)if(renderer!=null)foreach(var m in renderer.sharedMaterials)if(m==null||m.shader.name!="Universal Render Pipeline/Lit"||m.GetFloat("_Smoothness")>.21f)return false;return originalRoads.Count>0;}}public float MaximumRoadCoverage{get{float value=0;foreach(var renderer in originalRoads.Keys)if(renderer!=null)foreach(var m in renderer.sharedMaterials)if(m!=null&&m.HasProperty("_CoverageAmount"))value=Mathf.Max(value,m.GetFloat("_CoverageAmount"));return value;}}
 Rigidbody[] wheelBodies,traceBodies;SportsSnowBodyContact[] supports;float[] widths;bool[] mattress,tireBody;public int ScrapeContacts{get;private set;}Vector3[] prior;bool[] contact;float refresh;int stamp=int.MinValue,sprayCursor;bool wasRunning,observing;
 void Start(){PrepareRoadMaterials();surface.ConfigureVendorTextures(snowTexture,detailTexture,sparkleTexture);surface.ConfigureDepthRenderer(depthRenderer);surface.Initialize(new TruckTaxiSnowRegion(.3f),adapter);wheelBodies=new Rigidbody[wheels.Length];var powered=new System.Collections.Generic.HashSet<Rigidbody>();var broad=new System.Collections.Generic.HashSet<Rigidbody>(broadBodies);for(int i=0;i<wheels.Length;i++){wheelBodies[i]=wheels[i].GetComponentInParent<Rigidbody>();if(wheelBodies[i]!=null)powered.Add(wheelBodies[i]);}var tracked=new System.Collections.Generic.List<Rigidbody>();foreach(var body in FindObjectsByType<Rigidbody>(FindObjectsInactive.Include))if(body.gameObject.scene==gameObject.scene&&body.mass>=.05f&&body.GetComponentInParent<TruckTaxiPedestrian>()==null)tracked.Add(body);traceBodies=tracked.ToArray();supports=new SportsSnowBodyContact[traceBodies.Length];widths=new float[traceBodies.Length];mattress=new bool[traceBodies.Length];tireBody=new bool[traceBodies.Length];for(int i=0;i<traceBodies.Length;i++){var body=traceBodies[i];var support=body.GetComponent<SportsSnowBodyContact>();if(support==null)support=body.gameObject.AddComponent<SportsSnowBodyContact>();support.enabled=false;supports[i]=support;mattress[i]=broad.Contains(body);tireBody[i]=powered.Contains(body);float width=.25f;foreach(var c in body.GetComponentsInChildren<Collider>(true))if(!c.isTrigger&&c.attachedRigidbody==body)width=Mathf.Max(width,Mathf.Min(c.bounds.size.x,c.bounds.size.z));widths[i]=mattress[i]?3.15f:Mathf.Clamp(width,.2f,3.15f);}prior=new Vector3[wheels.Length+traceBodies.Length];contact=new bool[prior.Length];}
 bool Running=>session!=null?session.Running:cornhole!=null?cornhole.InMatch:cheese!=null&&cheese.match.InMatch;bool Live=>session!=null?session.Live:cornhole!=null?cornhole.InMatch&&!cornhole.Paused&&!cornhole.Finished:cheese!=null&&cheese.match.Live;
 void LateUpdate(){Falling=weather!=null?(weather.Kind==SportsWeatherKind.Snow||weather.Kind==SportsWeatherKind.Blizzard):cheese!=null?cheese.Kind==LWS.TruckCheeseRolling.CheeseWeatherKind.Blizzard:baseJump!=null&&baseJump.option==2;int current=weather!=null?weather.Seed:cheese!=null?cheese.match.Round:baseJump!=null?baseJump.Round:0;bool running=Running;if(current!=stamp||running&&!wasRunning){stamp=current;Coverage=Mathf.Max(permanentCoverage,Falling?.68f:0);surface.RefreshStreamedSurfaces();System.Array.Clear(contact,0,contact.Length);}wasRunning=running;if(Live)Coverage=Mathf.Clamp(Coverage+Time.deltaTime*(Falling?.018f:-.025f),permanentCoverage,1);surface.SetCoverage(Coverage);foreach(var pair in runtimeRoads){var material=pair.Value;var shader=Coverage>.001f?pair.Key.shader:Shader.Find("Universal Render Pipeline/Lit");if(material.shader!=shader)material.shader=shader;if(material.HasProperty("_CoverageAmount"))material.SetFloat("_CoverageAmount",Coverage);material.SetFloat("_Smoothness",.18f);}if(!surface.EnvironmentBindingsReady||Time.unscaledTime>=refresh){surface.Refresh();refresh=Time.unscaledTime+.25f;}Contacts=BroadContacts=ScrapeContacts=RoadContacts=0;if(!Live||Coverage<.06f){StopTraces();return;}SetObserving(true);int emitted=0;for(int i=0;i<wheels.Length;i++){var w=wheels[i];if(w==null||!w.enabled||!w.gameObject.activeInHierarchy||!w.IsGrounded||w.HitCollider==null||w.HitNormal.y<.25f||!Traceable(w.HitCollider,w.HitPoint,wheelBodies[i]!=null?wheelBodies[i].transform:w.transform,out _)){Stop(i);continue;}Traceable(w.HitCollider,w.HitPoint,wheelBodies[i]!=null?wheelBodies[i].transform:w.transform,out bool offRoad);Trace(i,w.HitPoint,Mathf.Max(.16f,w.wheel.width),wheelBodies[i],ref emitted,offRoad);Contacts++;if(!offRoad)RoadContacts++;}
 for(int b=0;b<traceBodies.Length;b++){int index=wheels.Length+b;var body=traceBodies[b];var support=supports[b];if(body==null||body.isKinematic||!body.gameObject.activeInHierarchy||!support.Supported||tireBody[b]&&!mattress[b]&&body.transform.up.y>.65f||!surface.IsSnowCoveredOffRoad(support.Surface,support.Point,body.transform)){Stop(index);continue;}Trace(index,support.Point,widths[b],body,ref emitted);if(mattress[b])BroadContacts++;else ScrapeContacts++;}}

 void Trace(int i,Vector3 p,float width,Rigidbody body,ref int emitted,bool offRoad=true){if(!contact[i]||(p-prior[i]).sqrMagnitude>=16){prior[i]=p;contact[i]=true;surface.StopWheelTrace(i);return;}var from=prior[i];if((p-from).sqrMagnitude<.0025f){surface.StopWheelTrace(i);return;}surface.TraceWheel(i,from,p,width,Coverage*.3f,offRoad);float speed=body!=null?body.GetPointVelocity(p).magnitude:0;if(spray.Length>0&&speed>1&&emitted++<8){var fx=spray[sprayCursor++%spray.Length];fx.transform.position=p+Vector3.up*.08f;var emit=new ParticleSystem.EmitParams{velocity=Vector3.up*Mathf.Clamp(speed*.12f,.25f,2)-Vector3.ClampMagnitude(body.linearVelocity,10)*.1f};fx.Emit(emit,Mathf.Clamp(Mathf.RoundToInt(speed*.3f),1,5));}prior[i]=p;contact[i]=true;}
 void PrepareRoadMaterials(){if(!traceExposedRoads)return;foreach(var road in FindObjectsByType<LwsRoadSurface>(FindObjectsInactive.Include))if(road.gameObject.scene==gameObject.scene)foreach(var renderer in road.GetComponentsInChildren<MeshRenderer>(true)){if(originalRoads.ContainsKey(renderer))continue;var original=renderer.sharedMaterials;var assigned=(Material[])original.Clone();bool changed=false;for(int i=0;i<assigned.Length;i++){var source=assigned[i];if(!LwsWeatheradeMaterialFactory.IsWeatheradeMaterialForMode(source,LwsWeatheradeSurfaceMaterialMode.Snow))continue;if(!runtimeRoads.TryGetValue(source,out var material)){material=new Material(source){name=source.name+" (isolated Sports road weather)"};material.SetFloat("_CoverageAmount",0);runtimeRoads.Add(source,material);}assigned[i]=material;changed=true;}if(changed){originalRoads.Add(renderer,original);renderer.sharedMaterials=assigned;}}}
 void OnDestroy(){foreach(var pair in originalRoads)if(pair.Key!=null)pair.Key.sharedMaterials=pair.Value;foreach(var material in runtimeRoads.Values)if(material!=null)Destroy(material);}
 bool Traceable(Collider shape,Vector3 point,Transform vehicle,out bool offRoad){offRoad=true;if(surface.IsSnowCoveredOffRoad(shape,point,vehicle))return true;if(!traceExposedRoads||shape==null||shape.isTrigger)return false;var road=shape.GetComponentInParent<LwsRoadSurface>();var taxi=shape.GetComponentInParent<TruckTaxiSurface>();if(road==null&&(taxi==null||!taxi.isRoad))return false;var renderer=shape.GetComponent<MeshRenderer>()??shape.GetComponentInParent<MeshRenderer>();if(renderer==null||!LwsWeatheradeMaterialFactory.IsWeatheradeMaterialForMode(renderer.sharedMaterial,LwsWeatheradeSurfaceMaterialMode.Snow))return false;int n=Physics.RaycastNonAlloc(point+Vector3.up*.15f,Vector3.up,exposure,128,~((1<<24)|(1<<25)),QueryTriggerInteraction.Ignore);if(n==exposure.Length)return false;for(int i=0;i<n;i++)if(vehicle==null||!exposure[i].transform.IsChildOf(vehicle))return false;offRoad=false;return true;}
 void Stop(int i){surface.StopWheelTrace(i);contact[i]=false;}void SetObserving(bool value){if(observing==value)return;observing=value;if(supports!=null)foreach(var support in supports)if(support!=null)support.enabled=value;}public void StopTraces(){SetObserving(false);if(contact==null)return;for(int i=0;i<contact.Length;i++)Stop(i);}void OnDisable(){StopTraces();if(spray!=null)foreach(var p in spray)if(p!=null)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
